CREATE TABLE ibexa_notification (id INT AUTO_INCREMENT NOT NULL, owner_id INT DEFAULT 0 NOT NULL, is_pending TINYINT(1) DEFAULT '1' NOT NULL, type VARCHAR(128) DEFAULT '' NOT NULL, created INT DEFAULT 0 NOT NULL, data LONGTEXT DEFAULT NULL, INDEX ibexa_notification_owner_is_pending (owner_id, is_pending), INDEX ibexa_notification_owner (owner_id), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
